head.script:
scwin.tData = {
    "description" : "[FAIL] gridView.getColumnVisible 가 MultiLine(Body 2줄) 그리드에서, 전체 컬럼 수(4)가 아닌 '한 줄당 컬럼 수'(columnOrder.length=2)를 기준으로 판정하여, 그 수를 넘는 고유 인덱스(3)를 표시 상태인데도 undefined 로 반환하는 결함 재현 (인덱스 0~2 만 정상. 3줄 샘플에선 인덱스 3·4·5 가 모두 undefined 로, 마지막 컬럼만의 문제가 아님이 확인됨)",
    "validation" : [
        "MultiLine(2줄) 이어도 모든 Column 은 고유 인덱스(0~3)를 가지므로, 모든 Column 이 표시된 상태에서 getColumnVisible(0~3)은 모두 true 를 반환해야 합니다.",
    ]
}

scwin.strNameSpace = 'xmlns:w2="http://www.inswave.com/websquare" xmlns:xf="http://www.w3.org/2002/xforms" xmlns:ev="http://www.w3.org/2001/xml-events"';

scwin.onpageload = function () {
    scwin.comp_init();
};

scwin.comp_init = async function () {
    if (typeof dlt_bind !== 'undefined') { $p.data.remove("dlt_bind"); }
    if (typeof gridMulti !== 'undefined') { gridMulti.remove(); }

    // MultiLine 그리드에 바인딩할 DataList (col1~col4)
    let strDlt = '';
    strDlt += '<w2:dataList ' + scwin.strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col2" name="col2" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col4" name="col4" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "col1": "서울 강남점", "col2": "1250", "col3": "김영업", "col4": "010-1111-2222" },
        { "col1": "부산 해운대점", "col2": "980", "col3": "이판매", "col4": "010-3333-4444" },
        { "col1": "대구 수성점", "col2": "1430", "col3": "박상담", "col4": "010-5555-6666" }
    ], false);

    // MultiLine 그리드 : 한 데이터 Row 가 2줄. 1줄 col1(고유 인덱스0)/col2(1), 2줄 col3(2)/col4(3)
    //  - 어떤 Column 도 숨기지 않는다(모두 표시 상태).
    let strMulti = '';
    strMulti += '<w2:gridView ' + scwin.strNameSpace + ' dataList="data:dlt_bind" id="gridMulti" style="width:560px;height:240px;">';
    strMulti += '<w2:caption id="capM" value="MultiLine (2줄, col1~col4 고유 인덱스 0~3, 숨긴 컬럼 없음)"></w2:caption>';
    strMulti += '<w2:header id="hM">';
    strMulti += '<w2:row id="hMr1"><w2:column width="280" inputType="text" id="hMcol1" value="지점명"></w2:column><w2:column width="*" inputType="text" id="hMcol2" value="매출"></w2:column></w2:row>';
    strMulti += '<w2:row id="hMr2"><w2:column width="280" inputType="text" id="hMcol3" value="담당자"></w2:column><w2:column width="*" inputType="text" id="hMcol4" value="연락처"></w2:column></w2:row>';
    strMulti += '</w2:header>';
    strMulti += '<w2:gBody id="gMb">';
    strMulti += '<w2:row id="gMr1"><w2:column width="280" inputType="text" id="col1" dataList="col1"></w2:column><w2:column width="*" inputType="text" id="col2" dataList="col2"></w2:column></w2:row>';
    strMulti += '<w2:row id="gMr2"><w2:column width="280" inputType="text" id="col3" dataList="col3"></w2:column><w2:column width="*" inputType="text" id="col4" dataList="col4"></w2:column></w2:row>';
    strMulti += '</w2:gBody>';
    strMulti += '</w2:gridView>';
    scwin.gridMulti = await $p.dynamicCreate("gridMulti", "gridView", strMulti, grp_comp);
}

// 결함 재현 : MultiLine 그리드에서 getColumnVisible(0~3) 을 호출해 반환값을 출력한다.
//  - 모든 Column 이 표시 상태이므로 0~3 모두 true 가 기대값.
//  - 실제로는 한 줄당 컬럼 수(columnOrder.length=2) 를 넘는 인덱스 3 이 undefined 로 반환됨(결함).
//    (엔진 useRealColIndex=true 분기: _colIndex > columnOrder.length 면 미반환. 3줄 샘플에선 3·4·5 가 모두 undefined)
scwin.btn_repro_onclick = function () {
    scwin.setReturnValue("getColumnVisible(0) : " + gridMulti.getColumnVisible(0));
    scwin.setReturnValue("getColumnVisible(1) : " + gridMulti.getColumnVisible(1));
    scwin.setReturnValue("getColumnVisible(2) : " + gridMulti.getColumnVisible(2));
    scwin.setReturnValue("getColumnVisible(3) : " + gridMulti.getColumnVisible(3));
}

// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
